import{_ as o,o as t,c as i,a5 as a}from"./chunks/framework.CsGesDJn.js";const u=JSON.parse('{"title":"Plan — OTP Verification","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-6-otp-verification/plan.md","filePath":"feature/authentication/3-2-6-otp-verification/plan.md"}'),n={name:"feature/authentication/3-2-6-otp-verification/plan.md"};function c(d,e,r,h,l,p){return t(),i("div",null,[...e[0]||(e[0]=[a('<h1 id="plan-—-otp-verification" tabindex="-1">Plan — OTP Verification <a class="header-anchor" href="#plan-—-otp-verification" aria-label="Permalink to &quot;Plan — OTP Verification&quot;">​</a></h1><p>&gt; <a href="./spec.html">spec.md</a> — 2 luồng OTP độc lập: email OTP (xác thực email Sign Up) + phone OTP (liên kết số điện thoại), cả hai gửi mã qua email.</p><h2 id="quyet-đinh-api" tabindex="-1">Quyết định API <a class="header-anchor" href="#quyet-đinh-api" aria-label="Permalink to &quot;Quyết định API&quot;">​</a></h2><p>Không có API tổng quát <code>otpSessionId</code> + <code>context</code> như bản spec cũ. Code hiện tại dùng 2 cặp API tách biệt theo mục đích:</p><ul><li><code>POST /api/v1/auth/verify-otp { email, otpCode }</code> + <code>POST /api/v1/auth/resend-otp { email }</code> — email OTP, không cần token.</li><li><code>POST /api/v1/auth/link/phone { phone }</code> + <code>POST /api/v1/auth/verify-phone-otp { otpCode }</code> — phone OTP, cần Bearer token (user đã đăng nhập).</li></ul><p>2FA dùng TOTP riêng (FR 3.2.7), KHÔNG qua OTP email. Reset Password dùng token qua link (FR 3.2.4), KHÔNG dùng OTP.</p><h2 id="ky-thuat" tabindex="-1">Kỹ thuật <a class="header-anchor" href="#ky-thuat" aria-label="Permalink to &quot;Kỹ thuật&quot;">​</a></h2><ul><li><code>AuthServiceImpl.verifyOtp(email, otpCode)</code> / <code>resendOtp(email)</code>: OTP lưu trực tiếp trên <code>users.otp_code</code>/<code>users.otp_expiry</code> (không phải Redis), Redis chỉ giữ counter sai (<code>otp:attempt:{email}</code>) và cooldown resend (<code>otp:resend:{email}</code>).</li><li><code>AuthServiceImpl.linkPhone(userId, phone)</code> / <code>verifyPhoneOtp(userId, otpCode)</code>: OTP + phone lưu chung 1 giá trị Redis <code>phone:otp:{userId}</code> = <code>&quot;&lt;otp&gt;:&lt;phone&gt;&quot;</code>, TTL 10 phút. Không có bảng nào lưu OTP phone ngoài Redis. Kèm 2 key phụ: <code>phone:otp:resend:{userId}</code> (cooldown 60s) và <code>phone:otp:attempt:{userId}</code> (đếm số lần sai, TTL 10 phút).</li><li>Cả 2 luồng đều gửi mã qua <code>mailService.sendOtpEmail</code> — phone OTP cũng đi qua email, không phải SMS dù tên field/route là &quot;phone&quot;.</li></ul><h2 id="data-model" tabindex="-1">Data Model <a class="header-anchor" href="#data-model" aria-label="Permalink to &quot;Data Model&quot;">​</a></h2><ul><li>Email OTP: cột <code>users.otp_code</code>, <code>users.otp_expiry</code>; Redis <code>otp:attempt:{email}</code> (TTL 10 phút), <code>otp:resend:{email}</code> (TTL 60s).</li><li>Phone OTP: Redis <code>phone:otp:{userId}</code> (TTL 10 phút), <code>phone:otp:resend:{userId}</code> (TTL 60s), <code>phone:otp:attempt:{userId}</code> (TTL 10 phút) — không có cột DB riêng, chỉ <code>users.phone</code> được set sau khi verify thành công.</li></ul><h2 id="rui-ro" tabindex="-1">Rủi ro <a class="header-anchor" href="#rui-ro" aria-label="Permalink to &quot;Rủi ro&quot;">​</a></h2><ul><li>Email OTP: brute force → giới hạn 5 lần thử (đã code), hủy OTP hiện tại khi vượt ngưỡng.</li><li>Phone OTP brute force: đã bổ sung giới hạn 5 lần thử sai (<code>phone:otp:attempt:{userId}</code>) — hủy OTP hiện tại khi vượt ngưỡng, và rate-limit resend 60s (<code>phone:otp:resend:{userId}</code>).</li><li>Phone OTP có race condition giữa link và verify (phone bị chiếm bởi user khác) — đã code check lại ở bước verify.</li></ul>',12)])])}const m=o(n,[["render",c]]);export{u as __pageData,m as default};
